    def _check_bounds_params(self):
        """Called after fitting to warn if bounds may have been too tight."""
        list_close = np.isclose(self.bounds, np.atleast_2d(self.theta).T)
        idx = 0
        for hyp in self.hyperparameters:
            if hyp.fixed:
                continue
            for dim in range(hyp.n_elements):
                if list_close[idx, 0]:
                    warnings.warn(
                        "The optimal value found for "
                        "dimension %s of parameter %s is "
                        "close to the specified lower "
                        "bound %s. Decreasing the bound and"
                        " calling fit again may find a "
                        "better value." % (dim, hyp.name, hyp.bounds[dim][0]),
                        ConvergenceWarning,
                    )
                elif list_close[idx, 1]:
                    warnings.warn(
                        "The optimal value found for "
                        "dimension %s of parameter %s is "
                        "close to the specified upper "
                        "bound %s. Increasing the bound and"
                        " calling fit again may find a "
                        "better value." % (dim, hyp.name, hyp.bounds[dim][1]),
                        ConvergenceWarning,
                    )
                idx += 1


def characteristic_length_scale(kernel, X=None):
    """Return the characteristic length scale of a kernel.

    If the kernel provides a characteristic_length_scale method, delegate to it.
    Otherwise, try to infer a length scale from hyperparameters or the kernel
    diagonal. This preserves the previous default behavior while allowing
    kernels to omit this method if they do not define a length scale.
    """
    method = getattr(kernel, "characteristic_length_scale", None)
    if callable(method):
        return method(X)
    params = kernel.get_params()
    for name, value in params.items():
        if "length_scale" in name and not name.endswith("_bounds"):
            return float(np.mean(np.atleast_1d(value)))
    if X is not None:
        diag_values = kernel.diag(X)
        return float(np.sqrt(np.mean(np.abs(diag_values)) + 1e-12))
    return 1.0


def smoothness_order(kernel):
    """Return the smoothness order of a kernel.

    Delegates to kernel.smoothness_order when available, otherwise uses the
    previous heuristic: stationary kernels -> 2.0, non-stationary -> 0.0.
    """
    method = getattr(kernel, "smoothness_order", None)
    if callable(method):
        return method()
    if kernel.is_stationary():
        return 2.0
    return 0.0


def suggested_regularization(kernel, X):
    """Suggest a regularization value for a kernel and data X.

    Delegates to kernel.suggested_regularization when available, otherwise
    uses the previous heuristic based on the kernel diagonal and characteristic
    length scale.
    """
    method = getattr(kernel, "suggested_regularization", None)
    if callable(method):
        return method(X)
    K_diag = kernel.diag(X)
    n_samples = _num_samples(X)
    diag_range = float(np.max(K_diag) - np.min(K_diag))
    scale = characteristic_length_scale(kernel, X)
    return (diag_range + 1e-10) / (n_samples * scale**2 + 1.0)


